-- Locale columns for exhibition/tour descriptions and highlights, plus
-- a one-time backfill translating every existing row into Russian and
-- Chinese so switching language actually translates the exhibition/tour
-- content itself, not just the surrounding page chrome.

ALTER TABLE exhibitions
  ADD COLUMN IF NOT EXISTS description_ru TEXT,
  ADD COLUMN IF NOT EXISTS description_zh TEXT,
  ADD COLUMN IF NOT EXISTS highlights_ru TEXT,
  ADD COLUMN IF NOT EXISTS highlights_zh TEXT;

ALTER TABLE tours
  ADD COLUMN IF NOT EXISTS description_ru TEXT,
  ADD COLUMN IF NOT EXISTS description_zh TEXT,
  ADD COLUMN IF NOT EXISTS highlights_ru TEXT,
  ADD COLUMN IF NOT EXISTS highlights_zh TEXT;

