UPDATE exhibitions SET
  description_ru = '7-я Гуанчжоуская ярмарка закупок пройдёт с 14 по 17 октября 2026 года в выставочном центре Poly World Trade Center Expo в Гуанчжоу, объединяя мировых покупателей с более чем 850 проверенными производителями.\n\nОсновные детали\nДаты: 14–17 октября 2026 года\nМесто проведения: Poly World Trade Center Expo (PWTC), Гуанчжоу, Китай.\nОрганизаторы: Global Sources, Poly Exhibition и Grandhub.\n\nКатегории продукции:\n\nСкобяные изделия и инструменты: ручной инструмент, электроинструмент, скобяные изделия для дома и строительства\n\nМашины и оборудование: механическая и электротехническая продукция, сварочное оборудование\n\nМотоциклы и аксессуары: мотоциклы, запчасти и инструменты для ремонта\n\nБытовая техника: техника для кухни, ванной и дома\n\nПочему стоит посетить\n\nСроки: проходит одновременно с расположенной поблизости Кантонской ярмаркой, что позволяет покупателям максимально использовать поездку.\n\nПодбор партнёров: бесплатный индивидуальный бизнес-мэтчинг для предварительно зарегистрированных и квалифицированных покупателей.',
  description_zh = '第七届广州采购展将于2026年10月14日至17日在广州保利世贸博览馆举行,连接全球买家与850多家经过认证的制造商。\n\n主要信息\n日期:2026年10月14日至17日\n地点:广州保利世贸博览馆(PWTC),中国广州\n主办方:环球资源、保利展览、Grandhub\n\n产品类别:\n\n五金工具:手动工具、电动工具、家用及建筑五金\n\n机械设备:机电产品、焊接设备\n\n摩托车及配件:摩托车、零件及维修工具\n\n家用电器:厨房、卫浴及家用电器\n\n为何参加\n\n时间安排:与邻近的广交会同期举行,方便买家充分利用行程。\n\n配对服务:为预先注册的合格买家提供免费一对一商务配对。',
  highlights_ru = '[\"🛠️ Инструменты\",\"🏍️ Мотоциклы\",\"Бытовая техника\",\"VIP-вход\",\"VIP-сервис\",\"🥂 Afterparty\",\"🍽 Ужин\",\"🛋 Бизнес-лаунж\",\"📋 Доступ к каталогу участников\",\"🎲 Розыгрыш призов\"]',
  highlights_zh = '[\"🛠️ 工具\",\"🏍️ 摩托车\",\"家用电器\",\"VIP入场\",\"VIP服务\",\"🥂 派对\",\"🍽 晚宴\",\"🛋 商务休息室\",\"📋 参展商名录访问权限\",\"🎲 抽奖活动\"]'
WHERE slug = 'the-7th-guangzhou-sourcing-fair';

