UPDATE tours SET
  description_ru = 'Пересеките границу с комфортом на частном автобусе прямо из Гуанчжоу до острова Лантау в Гонконге — крупнейшего острова Гонконга и дома всемирно известного Тянь Тань Будды («Большого Будды»).\n\nЗа три дня и две ночи вы прокатитесь на канатной дороге Ngong Ping 360, откуда открываются захватывающие виды на Южно-Китайское море, посетите тихий монастырь По Линь у подножия статуи Будды, прогуляетесь среди свайных домов и лавок с сушёными морепродуктами рыбацкой деревни Тай О, а также сможете свободно исследовать горизонт и набережную Гонконга перед тем, как автобус доставит вас обратно в Гуанчжоу.\n\nВ стоимость включены отель, автобусный трансфер в обе стороны и англоговорящий гид. Этот тур полностью настраиваемый — расскажите нам о вашей группе и интересах при регистрации, и мы адаптируем маршрут под вас.',
  description_zh = '乘坐私人巴士从广州舒适跨境直达香港最大的岛屿——大屿山,探访举世闻名的天坛大佛(\"大佛\")。\n\n三天两夜的行程中,您将乘坐昂坪360缆车饱览南中国海壮丽景色,参观位于大佛脚下宁静的宝莲禅寺,漫步于大澳渔村的棚屋与海味摊档之间,并在巴士送您返回广州之前,自由探索香港的天际线与海滨风光。\n\n行程已包含酒店住宿、往返巴士接送及英语导游。本行程可完全定制——报名时告诉我们您的团队和兴趣,我们将为您量身定制行程。',
  highlights_ru = '[\"Частный автобус, Гуанчжоу — остров Лантау и обратно\",\"Тянь Тань Будда («Большой Будда») и монастырь По Линь\",\"Поездка на канатной дороге Ngong Ping 360\",\"Рыбацкая деревня Тай О и свайные дома\",\"Включено проживание в отеле 2 ночи\",\"Англоговорящий гид\",\"Свободное время в Гонконге перед возвращением\"]',
  highlights_zh = '[\"私人巴士,广州往返大屿山\",\"天坛大佛(\\\"大佛\\\")与宝莲禅寺\",\"昂坪360缆车体验\",\"大澳渔村与棚屋\",\"含2晚酒店住宿\",\"英语导游\",\"返程前的香港自由活动时间\"]'
WHERE slug = 'guangzhou-lantau-island-hongkong-2night-tour';
